import{materials}from'../../core/index.js';import{THREE,mesh,box,circleHole,extrude,annulus}from'./geometry.js';import{spec}from'./dimensions.js';
function outline(){const s=new THREE.Shape(),x=10.4,r=3.35,a=Math.acos((x-8)/r),dy=Math.sqrt(r*r-(x-8)**2);s.moveTo(-7,-14.4);s.lineTo(-x,-11.4);s.lineTo(-x,-4-dy);s.absarc(-8,-4,r,Math.PI+a,Math.PI*3-a,false);s.lineTo(-x,11.4);s.lineTo(-7,14.4);s.lineTo(7,14.4);s.lineTo(x,11.4);s.lineTo(x,-4+dy);s.absarc(8,-4,r,a,Math.PI*2-a,false);s.lineTo(x,-11.4);s.lineTo(7,-14.4);s.lineTo(5.4,-14.4);s.lineTo(5.4,-9.4);s.lineTo(-5.4,-9.4);s.lineTo(-5.4,-14.4);s.closePath();circleHole(s,0,-4,2.2);for(const x of[-3,-1,1,3])circleHole(s,x,-8.54,.36);for(const x of spec.io.columnX)for(const y of spec.io.bendY)circleHole(s,x,y,.52);return s;}
export function electronics(host){const pcb=mesh(host.body,extrude(outline(),.8),materials.plastic(0x2a5941,{roughness:.9}),[0,0,-2.4],'Original U011 own inferred PCA9554PW PCB outline with real boss/Grove relief and through contact holes');pcb.userData={role:'physical-pcb',installationInferred:true};const metal=materials.metal(0xaeb3a3),dark=materials.plastic(0x252b23),pads=[],solder=[];for(const x of[-3,-1,1,3]){pads.push(mesh(host.body,annulus(.64,.36,.05),metal,[x,-8.54,-1.6],'U011 J1 plated through contact pad'));solder.push(mesh(host.body,annulus(.55,.19,.2),metal,[x,-8.54,-2.6],'U011 J1 retained solder collar'));}for(const x of spec.io.columnX)for(const y of spec.io.bendY)pads.push(mesh(host.body,annulus(.8,.52,.05),metal,[x,y,-1.6],'U011 P1 real annular PCB pad'));
 const chipFrame=new THREE.Group();chipFrame.position.set(0,3.2,-1.6);chipFrame.name='Original U011 PCA9554PW fixed TSSOP16 carrier;hidden placement inferred';host.body.add(chipFrame);const chip=box(chipFrame,[4.4,5.1,1.1],[0,0,.67],dark,'U011 U1 actual documentary PCA9554PW16-lead package envelope'),leads=[];
 for(let i=0;i<8;i++)for(const side of[-1,1]){const y=(i-3.5)*.65;leads.push(box(chipFrame,[.8,.3,.12],[side*2.8,y,.06],metal,'U011 U1 TSSOP16 solder foot'));leads.push(box(chipFrame,[.15,.3,.55],[side*2.5,y,.3],metal,'U011 U1 fixed gull-wing riser'));leads.push(box(chipFrame,[.65,.3,.12],[side*2.2,y,.6],metal,'U011 U1 fixed lead shoulder'));}
 const regulator=box(host.body,[3.8,2.3,1.25],[-6.9,4.1,-.975],dark,'U011 U2 HT7533 fixed package;envelope/install inferred'),regulatorLeads=[];for(let i=0;i<3;i++)regulatorLeads.push(box(host.body,[.55,1,.15],[-6.9+(i-1)*1.1,2.6,-1.525],metal,'U011 HT7533 fixed physical solder lead'));
 const passives=[],ends=[],positions=[[-7.4,8.1],[-7.4,6.3],[-7.4,1.5],[-7.4,-.3],[7.4,6.6],[7.4,4.7],[7.4,2.8],[7.4,.9],[-4.8,.3],[-2.8,.3],[-.8,.3],[1.2,.3],[3.2,.3],[-3,6.8],[-1,6.8],[1,6.8]];positions.forEach(([x,y],i)=>{passives.push(box(host.body,[1.25,.75,.45],[x,y,-1.375],materials.plastic(i<11?0x343a2f:0xb6a177),'U011 '+(i<11?'schematic resistor':'schematic capacitor')+' fixed appearance envelope'));for(const side of[-1,1])ends.push(box(host.body,[.22,.75,.48],[x+side*.54,y,-1.36],metal,'U011 fixed passive metal termination'));});
 const interruptPad=mesh(host.body,new THREE.CylinderGeometry(.48,.48,.05,32).rotateX(Math.PI/2),metal,[-4.5,3.5,-1.575],'U011 JP1 actual documented INT test pad;hidden installation inferred,no external Port');return{pcb,pads,solder,chipFrame,chip,leads,regulator,regulatorLeads,passives,ends,interruptPad};}
